import os


class Config:
    # -------------------------------------------------------------------------
    # Directory and File Paths
    # -------------------------------------------------------------------------
    INPUT_DIR = "./input"
    METADATA_DIR = "./metadata"
    WORKING_DIR = "./working/idea_4"
    SUBMISSION_DIR = "./submission"

    # Ensure necessary directories exist
    os.makedirs(WORKING_DIR, exist_ok=True)
    os.makedirs(SUBMISSION_DIR, exist_ok=True)

    # Metadata CSVs (generated by the metadata script)
    TRAIN_CSV = os.path.join(METADATA_DIR, "train.csv")
    VAL_CSV = os.path.join(METADATA_DIR, "val.csv")
    TEST_CSV = os.path.join(METADATA_DIR, "test.csv")

    # Cache Files for Processed Data (using .npz for efficient storage)
    TRAIN_CACHE = os.path.join(WORKING_DIR, "train_data.npz")
    VAL_CACHE = os.path.join(WORKING_DIR, "val_data.npz")
    TEST_CACHE = os.path.join(WORKING_DIR, "test_data.npz")

    # Model Checkpoint
    MODEL_PATH = os.path.join(WORKING_DIR, "best_model.pt")
    SUBMISSION_PATH = os.path.join(SUBMISSION_DIR, "submission.csv")

    # -------------------------------------------------------------------------
    # Data Dimensions and Features
    # -------------------------------------------------------------------------
    # Atomic Stream Features:
    # 1. One-hot encoding of element type (Al, Ga, In, O) -> 4 dims
    # 2. Centered Cartesian coordinates (x, y, z) -> 3 dims
    # 3. Nearest neighbor distance -> 1 dim
    ATOM_INPUT_DIM = 4 + 3 + 1  # Total: 8

    # Global Stream Features:
    # 1. Lattice vector lengths (lv1, lv2, lv3) -> 3 dims
    # 2. Lattice angles (alpha, beta, gamma) -> 3 dims
    # 3. Total number of atoms -> 1 dim
    # 4. Composition percentages (Al, Ga, In) -> 3 dims
    # 5. Unit cell volume -> 1 dim
    # 6. Atomic density -> 1 dim
    GLOBAL_INPUT_DIM = 3 + 3 + 1 + 3 + 1 + 1  # Total: 12

    # Target Variables
    TARGET_COLS = ["formation_energy_ev_natom", "bandgap_energy_ev"]
    NUM_TARGETS = len(TARGET_COLS)

    # -------------------------------------------------------------------------
    # Model Architecture Hyperparameters
    # -------------------------------------------------------------------------
    # Dimension of the hidden layers in the MLPs
    HIDDEN_DIM = 512  # Increased from 256. Cite solution_lesson_node_00017

    # Dimension of the latent representation after pooling
    # Note: We use concatenation of Mean and Max pooling, so the fused vector
    # before the final regressor will be larger.
    LATENT_DIM = 512  # Increased from 256. Cite solution_lesson_node_00017

    # Dropout rate for regularization
    DROPOUT = 0.1

    # -------------------------------------------------------------------------
    # Training Hyperparameters
    # -------------------------------------------------------------------------
    BATCH_SIZE = 64
    LEARNING_RATE = 1e-3
    NUM_EPOCHS = 200  # Increased from 150. Cite solution_lesson_node_00017
    PATIENCE = 20  # Increased from 15
    WEIGHT_DECAY = 1e-5  # L2 Regularization

    # Random Seed for Reproducibility
    SEED = 42
